use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm;

struct Node;

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // `requires len(question) <= 512` holds of every input, so we may
        // rely on the question being bounded; no revalidation is needed here.

        let system = "You are a customer support agent. Answer the user's \
                      question. When you need facts from the knowledge base, \
                      ask for the `lookup` tool with a focused query; \
                      otherwise answer directly.";

        let mut prompt = String::new();
        prompt.push_str("Intent: ");
        prompt.push_str(intent_label(ctx.intent));
        prompt.push_str("\nQuestion: ");
        prompt.push_str(&ctx.question);
        if !ctx.knowledge.is_empty() {
            prompt.push_str("\n\nKnowledge provided:\n");
            for k in &ctx.knowledge {
                prompt.push_str("- ");
                prompt.push_str(k);
                prompt.push('\n');
            }
        }

        // Tool-orchestration loop. The only tool this node holds is the
        // read-only knowledge-base lookup; any other requested tool is
        // outside the grant and is refused as an error value.
        const MAX_ROUNDS: usize = 8;
        for _ in 0..MAX_ROUNDS {
            match tool_llm::generate(&system, &prompt) {
                tool_llm::Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                tool_llm::Reply::Call(req) => {
                    if req.tool == "lookup" {
                        let results = kb_read::lookup(&req.query);
                        prompt.push_str("\n\nLookup results for \"");
                        prompt.push_str(&req.query);
                        prompt.push_str("\":\n");
                        if results.is_empty() {
                            prompt.push_str("(no matching entries)\n");
                        } else {
                            for r in &results {
                                prompt.push_str("- ");
                                prompt.push_str(r);
                                prompt.push('\n');
                            }
                        }
                    } else {
                        return ResponseResult::Error(LlmError {
                            message: format!(
                                "requested tool `{}` is not in this node's scope",
                                req.tool
                            ),
                        });
                    }
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "exceeded maximum tool-call rounds without an answer".to_string(),
        })
    }
}

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

export!(Node);
